// ALL THRESHOLDS LIVE HERE. Change a number here and nothing else needs to change.
const RULES = {
  alertFromPoints: 6,

  usageDropLarge: { atOrBelowPct: -30, points: 3 },
  usageDrop: { atOrBelowPct: -15, points: 2 },
  lowActiveUsers: { belowPct: 30, points: 2 },
  openTickets: { atLeast: 3, points: 2 },
  noContactLong: { overDays: 45, points: 2 },
  noContact: { overDays: 30, points: 1 },
  renewalVerySoon: { withinDays: 30, points: 3 },
  renewalSoon: { withinDays: 60, points: 2 },

  dedupWindowDays: 7,
  dedupMinScoreRise: 2,
  dedupBlockingStatuses: ['pending review', 'approved'],
};

const today = $now.setZone('Europe/Warsaw').startOf('day');

// An empty cell must stay empty. Number(null) would turn it into 0.
const toNumber = (value) => {
  if (value === null || value === undefined || value === '') return null;
  return Number.isNaN(Number(value)) ? null : Number(value);
};

return $input.all().map((item) => {
  const account = item.json;
  const usage = toNumber(account.usage_change_30d_pct);
  const activeUsers = toNumber(account.active_users_pct);
  const tickets = toNumber(account.open_tickets);
  const contactDays = toNumber(account.days_since_last_contact);
  const renewal = DateTime.fromISO(String(account.renewal_date || '').slice(0, 10), { zone: 'Europe/Warsaw' });
  const daysToRenewal = renewal.isValid ? Math.round(renewal.diff(today, 'days').days) : null;

  let score = 0;
  const reasons = [];
  const signals = [];
  const dataChecks = [];
  const addPoints = (points, text, signal) => {
    score += points;
    reasons.push(text + ' (+' + points + ')');
    signals.push(signal);
  };

  if (usage === null) dataChecks.push('usage change missing');
  else if (usage <= RULES.usageDropLarge.atOrBelowPct) addPoints(RULES.usageDropLarge.points, 'Usage down ' + Math.abs(usage) + '% in 30 days', 'usageDrop');
  else if (usage <= RULES.usageDrop.atOrBelowPct) addPoints(RULES.usageDrop.points, 'Usage down ' + Math.abs(usage) + '% in 30 days', 'usageDrop');

  if (activeUsers === null) dataChecks.push('active users missing');
  else if (activeUsers < RULES.lowActiveUsers.belowPct) addPoints(RULES.lowActiveUsers.points, 'Only ' + activeUsers + '% of users active', 'lowActiveUsers');

  if (tickets === null) dataChecks.push('open tickets missing');
  else if (tickets >= RULES.openTickets.atLeast) addPoints(RULES.openTickets.points, tickets + ' open tickets', 'openTickets');

  if (contactDays === null) dataChecks.push('last contact missing');
  else if (contactDays > RULES.noContactLong.overDays) addPoints(RULES.noContactLong.points, 'No contact for ' + contactDays + ' days', 'noContact');
  else if (contactDays > RULES.noContact.overDays) addPoints(RULES.noContact.points, 'No contact for ' + contactDays + ' days', 'noContact');

  if (daysToRenewal === null) dataChecks.push('renewal date missing');
  else if (daysToRenewal < 0) dataChecks.push('renewal date has passed');
  else if (daysToRenewal <= RULES.renewalVerySoon.withinDays) addPoints(RULES.renewalVerySoon.points, 'Renewal in ' + daysToRenewal + ' days', 'renewalVerySoon');
  else if (daysToRenewal <= RULES.renewalSoon.withinDays) addPoints(RULES.renewalSoon.points, 'Renewal in ' + daysToRenewal + ' days', 'renewalSoon');

  if (dataChecks.length) reasons.push('Data check: ' + dataChecks.join(', '));

  return {
    json: {
      ...account,
      days_to_renewal: daysToRenewal,
      risk_score: score,
      risk_reasons: reasons.join('; '),
      risk_signals: signals,
      over_threshold: score >= RULES.alertFromPoints,
      dedup_window_days: RULES.dedupWindowDays,
      dedup_min_score_rise: RULES.dedupMinScoreRise,
      dedup_blocking_statuses: RULES.dedupBlockingStatuses,
    },
  };
});

const accounts = $('Score accounts').all();
const savedAlerts = $input.all().map((item) => item.json).filter((row) => row.account_id);
const today = $now.setZone('Europe/Warsaw').startOf('day');

const daysAgo = (date) => {
  const day = DateTime.fromISO(String(date).slice(0, 10), { zone: 'Europe/Warsaw' });
  return Math.round(today.diff(day, 'days').days);
};

// An alert whose AI draft failed does not block: the account gets a fresh try the next day.
const draftFailed = (row) => String(row.internal_note || '').startsWith('NO DRAFT');

return accounts.map((item) => {
  const account = item.json;

  // The eval brings its own past alerts, so it never touches the real table.
  const history = account.eval_run
    ? (account.eval_prior_alerts || [])
    : savedAlerts.filter((row) => row.account_id === account.account_id);

  const blocking = history.filter((row) =>
    daysAgo(row.alert_date) <= account.dedup_window_days &&
    account.dedup_blocking_statuses.includes(String(row.review_status).trim().toLowerCase()) &&
    !draftFailed(row)
  );
  const lastScore = blocking.length ? Math.max(...blocking.map((row) => Number(row.score))) : null;
  const rose = lastScore !== null && account.risk_score >= lastScore + account.dedup_min_score_rise;

  let createAlert = false;
  let decision = 'Below threshold';
  if (account.over_threshold && lastScore === null) {
    createAlert = true;
    decision = 'New alert';
  } else if (account.over_threshold && rose) {
    createAlert = true;
    decision = 'New alert: score rose from ' + lastScore + ' to ' + account.risk_score;
  } else if (account.over_threshold) {
    decision = 'Skipped: open alert with score ' + lastScore;
  }

  return { json: { ...account, create_alert: createAlert, decision } };
});

// Fixed rules pick ONE topic per email, so the AI never decides what to say.
// The AI gets only the topic, the ask and at most one fact. No name, no metrics, no notes.
const TOPICS = {
  renewal: {
    label: 'their upcoming renewal',
    ask: 'Would a short written summary of what they use today and what is still open be useful before the renewal? A yes is enough.',
    check: 'Confirm the renewal date and contract terms in the CRM.',
  },
  tickets: {
    label: 'their open support requests',
    ask: 'Which one open request matters most to them right now? They can reply with just its subject, and it will be flagged to the support team as their priority.',
    check: 'Read the open tickets, so you can answer about them by name.',
  },
  adoption: {
    label: 'getting more of their team set up',
    ask: 'Would a short setup guide they can forward to colleagues who have not started yet be useful? A yes is enough.',
    check: 'Check which users are inactive and whether the main contact changed.',
  },
  usage: {
    label: 'whether the product still fits how they work',
    ask: 'Would a short list of the features teams like theirs use most be useful? A yes is enough.',
    check: 'Check which features dropped before sending.',
  },
  contact: {
    label: 'a check-in after a quiet period',
    ask: 'Would a short written update on what changed in the product recently be useful? A yes is enough.',
    check: 'Read the last conversation in the CRM.',
  },
};

// Most urgent and most useful for the customer first.
const PRIORITY = [
  ['renewalVerySoon', 'renewal'],
  ['openTickets', 'tickets'],
  ['lowActiveUsers', 'adoption'],
  ['usageDrop', 'usage'],
  ['renewalSoon', 'renewal'],
  ['noContact', 'contact'],
];

return $input.all().map((item) => {
  const a = item.json;
  const signals = a.risk_signals || [];
  const match = PRIORITY.find(([signal]) => signals.includes(signal));
  const topicKey = match ? match[1] : 'contact';
  const topic = TOPICS[topicKey];

  let fact = '';
  if (topicKey === 'renewal') {
    fact = 'Renewal date: ' + DateTime.fromISO(String(a.renewal_date).slice(0, 10)).setLocale('en-GB').toFormat('d MMMM');
  } else if (topicKey === 'tickets') {
    fact = 'Open support requests: ' + a.open_tickets;
  }

  return {
    json: {
      account_id: a.account_id,
      account_name: a.account_name,
      risk_score: a.risk_score,
      risk_reasons: a.risk_reasons,
      topic: topicKey,
      topic_label: topic.label,
      ask: topic.ask,
      allowed_fact: fact,
      internal_note: [
        'Email topic: ' + topic.label + '.',
        'Before sending: ' + topic.check,
        'CSM note: ' + (a.csm_note || '-'),
      ].join('\n'),
    },
  };
});

const briefs = $('Build email brief').all();
const today = $now.setZone('Europe/Warsaw').toFormat('yyyy-MM-dd');

const freeWork = /(?<!feel )\b(free|complimentary|no charge|no cost|on the house|on us|discount|refund|credit)\b/i;
const promise = /\b(we will|we'll|i will|i'll)\s+(fix|resolve|solve|set up|build|handle|migrate|take care)\b|\bguarantee|as soon as possible|right away|walk you through/i;
const meeting = /\b(call|meeting|meet|demo|zoom|jump on|hop on|next week)\b/i;
const internalWords = /\b(churn|risk|score|points?|mrr|revenue|threshold|flagged|usage|active users|inactive|dropped|decline)\b/i;
const weakPhrases = /(wanted to reach out|reaching out|hope (this|you|all)|checking in|quick question|touch base|circle back|finds you well|do not hesitate|don't hesitate|valued customer|leverage|synergy)/i;
const countWords = (text) => text.trim().split(/\s+/).filter(Boolean).length;

return $input.all().map((item, i) => {
  const brief = briefs[i].json;
  const text = (item.json.content || [])
    .filter((block) => block.type === 'text')
    .map((block) => block.text)
    .join('\n')
    .replace(/```json|```/g, '')
    .trim();

  let result = {};
  const problems = [];
  const checks = [];

  if (item.json.error) {
    problems.push('AI call failed after retries');
  } else {
    try {
      result = JSON.parse(text);
    } catch (error) {
      problems.push('AI result is not valid JSON');
    }
  }

  let subject = typeof result.subject === 'string' ? result.subject.trim() : '';
  let body = typeof result.body === 'string' ? result.body.trim() : '';

  if (!problems.length && (!subject || !body)) problems.push('Subject or body is empty');

  if (!problems.length) {
    const draft = subject + ' ' + body;
    const allowed = new Set(brief.allowed_fact.match(/\d+/g) || []);
    const unknown = (draft.match(/\d+/g) || []).filter((n) => !allowed.has(n));
    if (unknown.length) checks.push('Number not in the brief: ' + unknown.join(', '));
    if (!body.startsWith('Hi [ACCOUNT] team,')) checks.push('Unexpected greeting');
    if (freeWork.test(draft)) checks.push('Possible free work or discount');
    if (promise.test(draft)) checks.push('Possible promise');
    if (meeting.test(draft)) checks.push('Suggests a call or meeting');
    if (internalWords.test(draft)) checks.push('Internal or monitoring word');
    if (weakPhrases.test(draft)) checks.push('Generic or corporate phrase');
    if (countWords(body) > 90) checks.push('Email too long: ' + countWords(body) + ' words');
    if (!body.endsWith('Customer Success')) checks.push('Sign-off is missing');

    // The real name is added only now, so it never went to the AI.
    subject = subject.split('[ACCOUNT]').join(brief.account_name);
    body = body.split('[ACCOUNT]').join(brief.account_name);
    if (/\[[A-Z_]+\]/.test(subject + body)) checks.push('Placeholder left in the text');
  }

  const internalNote = problems.length
    ? 'NO DRAFT: ' + problems.join(', ') + '. Write the email by hand.\n' + brief.internal_note
    : [brief.internal_note, checks.length ? 'AUTO-CHECK: ' + checks.join(' | ') : ''].filter(Boolean).join('\n');

  return {
    json: {
      account_id: brief.account_id,
      alert_date: today,
      score: brief.risk_score,
      reasons: brief.risk_reasons,
      draft_subject: subject,
      draft_body: body,
      internal_note: internalNote,
    },
  };
});
